mapper.select:
WITH order_rows AS ( SELECT CAST(om.room_id AS CHAR) AS roomId, CAST(om.order_id AS CHAR) AS orderId, om.status AS orderStatus, om.payment_status AS paymentStatus, om.guest_name AS guestName, om.guest_mobile AS guestMobile, om.remark AS orderRemark, CAST(ca.channel_id AS CHAR) AS channelId, ca.channel_name AS channelName, om.start_at AS checkInAt, om.end_at AS checkOutAt, om.total_price_cent AS totalPriceCent, om.total_pay_price_cent AS totalPayPriceCent, om.source_type AS sourceType FROM order_main om LEFT JOIN channel_account ca ON ca.account_id = om.channel_id AND ca.camp_id = om.camp_id WHERE om.camp_id = #{campId} AND om.is_deleted = 0 AND om.room_id IS NOT NULL AND om.status NOT IN ('cancelled', 'canceled') AND om.start_at < #{nextDayStart} AND om.end_at > #{dayStart} ) SELECT CAST(r.room_id AS CHAR) AS roomId, r.room_name AS roomName, CAST(r.poi_id AS CHAR) AS poiId, CAST(r.room_category_id AS CHAR) AS roomCategoryId, rc.name AS roomCategoryName, rc.sort_no AS roomCategorySeq, CAST(rc.group_id AS CHAR) AS roomCategoryGroupId, CAST(r.floor_id AS CHAR) AS floorId, rf.floor_name AS floorName, rf.sort_no AS floorSeq, r.clean_status AS cleanStatus, r.sale_type AS saleType, r.sort_no AS roomSeq, ro.orderId AS orderId, ro.orderStatus AS orderStatus, ro.paymentStatus AS paymentStatus, ro.guestName AS guestName, ro.guestMobile AS guestMobile, ro.orderRemark AS orderRemark, ro.channelId AS channelId, ro.channelName AS channelName, ro.checkInAt AS checkInAt, ro.checkOutAt AS checkOutAt, ro.totalPriceCent AS totalPriceCent, ro.totalPayPriceCent AS totalPayPriceCent, ro.sourceType AS sourceType FROM room r JOIN room_category rc ON rc.room_category_id = r.room_category_id AND rc.camp_id = r.camp_id AND rc.status = 1 AND rc.is_deleted = 0 LEFT JOIN room_floor rf ON rf.floor_id = r.floor_id AND rf.camp_id = r.camp_id AND rf.status = 1 AND rf.is_deleted = 0 LEFT JOIN order_rows ro ON ro.roomId = CAST(r.room_id AS CHAR) WHERE r.camp_id = #{campId} AND r.status = 1 AND r.is_deleted = 0
AND rc.group_id IN
#{roomCategoryGroupId}
AND r.room_category_id IN
#{roomCategoryId}
AND r.poi_id IN
#{poiId}
ORDER BY rc.sort_no ASC, rc.room_category_id ASC, rf.sort_no ASC, rf.floor_id ASC, r.sort_no ASC, r.room_id ASC, CASE WHEN ro.orderStatus = 'checked_in' THEN 1 WHEN ro.orderStatus = 'booked' THEN 2 WHEN ro.orderStatus = 'pending' THEN 3 WHEN ro.orderStatus = 'refunding' THEN 4 ELSE 9 END ASC, ro.checkInAt ASC, ro.orderId ASC
